/// セグメント木に乗せる演算を表すtrait
///
/// - 最小値 : identity → i64::MAX
/// - 最大値 : identity → i64::MIN
/// - 合計　 : identity → 0
///
/// operate は区間同士を結合する演算
/// min, max, sum などが入る
pub trait SegmentTreeOperator<T: Copy> {
    /// 単位元を返す
    fn identity() -> T;

    /// 2つの値を結合する
    fn operate(left: T, right: T) -> T;
} // end of trait

/// 通常のセグメント木
///
/// - 一点変更 set O(logN)
/// - 一点加算 add O(logN)
/// - 区間取得 query O(logN)
///
/// 外から渡すindexは0-indexed
/// queryは半開区間 [left, right)
pub struct SegmentTree<T, Op>
where
    T: Copy,
    Op: SegmentTreeOperator<T>,
{
    /// 元配列の長さ
    original_len: usize,

    /// 葉の数, 2のべき乗になるように拡張する
    leaf_len: usize,

    /// セグメント木本体
    /// node[1] → root
    /// node[0] → 使用しない
    node: Vec<T>,

    /// Opを型として持つためのマーカー
    /// 実際の値は持たない
    _marker: PhantomData<Op>,
} // end of struct

impl<T, Op> SegmentTree<T, Op>
where
    T: Copy,
    Op: SegmentTreeOperator<T>,
{
    // ======================================================================================
    //
    //                                        構築・基本参照
    //
    // ======================================================================================

    /// 配列からセグメント木を構築
    pub fn new(values: &[T]) -> Self {
        let original_len: usize = values.len();

        // 葉の数を2のべき乗まで増やす
        let mut leaf_len: usize = 1;
        while leaf_len < original_len {
            leaf_len <<= 1;
        }

        // 単位元で初期化, node[1]から使用
        let mut node = vec![Op::identity(); leaf_len << 1];

        // 元配列を葉に入れる
        node[leaf_len..(leaf_len + original_len)].copy_from_slice(values);

        // 下から親を構築
        for i in (1..leaf_len).rev() {
            node[i] = Op::operate(node[i << 1], node[(i << 1) | 1]);
        }

        return Self {
            original_len,
            leaf_len,
            node,
            _marker: PhantomData,
        };
    } // end of constructor

    /// 長さsizeのセグメント木を単位元で構築
    pub fn new_empty(size: usize) -> Self {
        let values = vec![Op::identity(); size];
        return Self::new(&values);
    } // end of constructor

    /// 元配列の長さを返す
    #[inline(always)]
    pub fn len(&self) -> usize {
        return self.original_len;
    } // end of method

    /// 空かどうかを返す
    #[inline(always)]
    pub fn is_empty(&self) -> bool {
        return self.original_len == 0;
    } // end of method

    /// index番目の値を返す
    #[inline(always)]
    pub fn get(&self, index: usize) -> T {
        debug_assert!(index < self.original_len, "index is out of range");

        return self.node[self.leaf_len + index];
    } // end of method

    /// 全体の値を取得
    #[inline(always)]
    pub fn all(&self) -> T {
        return self.node[1];
    } // end of method

    // ======================================================================================
    //
    //                                        セグ木メソッド
    //
    // ======================================================================================

    /// index番目の値をvalueに変更
    #[inline(always)]
    pub fn set(&mut self, index: usize, value: T) {
        debug_assert!(index < self.original_len, "index is out of range");

        // 葉の位置に移動
        let mut pos = self.leaf_len + index;

        // 葉を更新
        self.node[pos] = value;

        // 親を更新
        while pos > 1 {
            pos >>= 1;
            self.node[pos] = Op::operate(self.node[pos << 1], self.node[(pos << 1) | 1]);
        }
    } // end of method

    /// 半開区間[left, right) の値を取得
    #[inline(always)]
    pub fn query(&self, left: usize, right: usize) -> T {
        debug_assert!(left <= right, "left must be less than or equal to right");
        debug_assert!(right <= self.original_len, "right is out of range");

        let mut l = left + self.leaf_len;
        let mut r = right + self.leaf_len;

        // 左右から集計
        let mut left_result = Op::identity();
        let mut right_result = Op::identity();

        while l < r {
            // Lが右の子なら、そのノードを使ってから右へ
            if (l & 1) == 1 {
                left_result = Op::operate(left_result, self.node[l]);
                l += 1;
            }

            // Rが右の子なら、左隣のノードを使って左へ
            if (r & 1) == 1 {
                r -= 1;
                right_result = Op::operate(self.node[r], right_result);
            }

            // 親へ
            l >>= 1;
            r >>= 1;
        }

        return Op::operate(left_result, right_result);
    } // end of method
} // end of impl SegmentTree

impl<T, Op> SegmentTree<T, Op>
where
    T: Copy + Add<Output = T>,
    Op: SegmentTreeOperator<T>,
{
    /// index番目にdeltaを加算
    ///
    /// sum以外に min/max にも使用可能
    /// Tに + の加算が定義されている必要がある
    pub fn add(&mut self, index: usize, delta: T) {
        debug_assert!(index < self.original_len, "index is out of range");

        // 現在地を取得
        let current = self.get(index);

        // 現在地 + delta に変更
        self.set(index, current + delta);
    } // end of method
} // end of impl SegmentTree(Add)

/// min/max の単位元を返すtrait
/// Rust標準には 整数/浮動小数 まとめて最大/最小を返す共通traitが無いので自作
pub trait MinMaxValue: Copy + PartialOrd {
    /// 区間最小の単位元
    /// min(x, INF) = x になる値
    fn min_identity() -> Self;

    /// 区間最大の単位元
    /// max(x, -INF) = x になる値
    fn max_identity() -> Self;
} // end of trait

/// sum のゼロを返すtrait
/// Rust標準のDefaultでも可能, 意図を明確にするために min/max 同様に自作
pub trait ZeroValue: Copy + Add<Output = Self> {
    /// 加算の単位元
    /// x + 0 = x になる
    fn zero() -> Self;
} // end of trait

/// 整数型に MinMaxValue を実装するマクロ
macro_rules! impl_min_max_value_for_integer {
	($($t:ty), +) => {
		$(
			impl MinMaxValue for $t{
				#[inline(always)]
				fn min_identity() -> Self {
					return <$t>::MAX;
				}

				#[inline(always)]
				fn max_identity() -> Self {
					return <$t>::MIN;
				}
			}
		)+
	};
} // end of macro

/// 浮動小数型に MinMaxValue を実装するマクロ
macro_rules! impl_min_max_value_for_float {
	($($t: ty), +) => {
		$(
			impl MinMaxValue for $t{
				#[inline(always)]
				fn min_identity() -> Self{
					return <$t>::INFINITY;
				}

				#[inline(always)]
				fn max_identity() -> Self {
					return <$t>::NEG_INFINITY;
				}
			}
		)+
	};
} // end of macro

/// 数値型に ZeroValue を実装するマクロ
macro_rules! impl_zero_value {
	($($t:ty), +) => {
		$(
			impl ZeroValue for $t {
				#[inline(always)]
				fn zero() -> Self {
					return 0 as $t;
				}
			}
		)+
	};
} // end of macro

/// 整数型/浮動小数型 にmin/max/zeroを実装
impl_min_max_value_for_integer!(i8, i16, i32, i64, i128, isize, u8, u16, u32, u64, u128, usize);
impl_min_max_value_for_float!(f32, f64);
impl_zero_value!(i8, i16, i32, i64, i128, isize, u8, u16, u32, u64, u128, usize, f32, f64);

/// 任意の数値型 T の区間最小値
pub struct MinNum<T>
where
    T: Copy,
{
    _marker: PhantomData<T>,
} // end of struct

impl<T> SegmentTreeOperator<T> for MinNum<T>
where
    T: MinMaxValue,
{
    /// 区間最小の単位元
    #[inline(always)]
    fn identity() -> T {
        return T::min_identity();
    } // end of method

    /// Min(a, b) の実装
    #[inline(always)]
    fn operate(left: T, right: T) -> T {
        if left <= right {
            return left;
        } else {
            return right;
        }
    } // end of method
} // end of impl Min SegmentTree

/// 任意の数値型 T の区間最大
pub struct MaxNum<T>
where
    T: Copy,
{
    _marker: PhantomData<T>,
} // end of struct

impl<T> SegmentTreeOperator<T> for MaxNum<T>
where
    T: MinMaxValue,
{
    /// 区間最大の単位元
    #[inline(always)]
    fn identity() -> T {
        return T::max_identity();
    } // end of method

    /// Max(a, b) の実装
    #[inline(always)]
    fn operate(left: T, right: T) -> T {
        if left >= right {
            return left;
        } else {
            return right;
        }
    } // end of method
} // end of impl Max SegmentTree

/// 任意の数値型 T の区間合計
pub struct SumNum<T>
where
    T: Copy,
{
    _marker: PhantomData<T>,
} // end of struct

impl<T> SegmentTreeOperator<T> for SumNum<T>
where
    T: ZeroValue,
{
    /// 加算の単位元
    #[inline(always)]
    fn identity() -> T {
        return T::zero();
    } // end of method

    /// Add(a, b) の実装
    #[inline(always)]
    fn operate(left: T, right: T) -> T {
        return left + right;
    } // end of method
} // end of impl Sum SegmentTree
